// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        try c.sendMoney(address(c), depositAmount) {} catch { return; }
        uint256 midDeposits;
        try c.depositsCount() returns (uint256 __r) { midDeposits = __r; } catch { return; }
        uint midBalance = address(c).balance;
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(withdrewReverted ? (afterDeposits == midDeposits && afterBalance == midBalance) : (afterBalance == 0 && afterDeposits == midDeposits));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
